import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Backlog — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"backlog-02-how-tos-and-workflows.md","filePath":"backlog-02-how-tos-and-workflows.md"}'),r={name:"backlog-02-how-tos-and-workflows.md"};function n(l,e,s,d,u,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="backlog-—-how-tos-workflows" tabindex="-1">Backlog — How-tos &amp; Workflows <a class="header-anchor" href="#backlog-—-how-tos-workflows" aria-label="Permalink to &quot;Backlog — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Backlog workflows</em></p><hr><h2 id="creating-a-feature" tabindex="-1">Creating a Feature <a class="header-anchor" href="#creating-a-feature" aria-label="Permalink to &quot;Creating a Feature&quot;">​</a></h2><h3 id="option-a-directly-in-the-backlog" tabindex="-1">Option A: Directly in the Backlog <a class="header-anchor" href="#option-a-directly-in-the-backlog" aria-label="Permalink to &quot;Option A: Directly in the Backlog&quot;">​</a></h3><p>The most straightforward way to add a Feature is directly from the Backlog.</p><ol><li>Navigate to the Backlog from the left-hand navigation.</li><li>Click the Add Feature button (or equivalent entry point in the backlog).</li><li>Enter a Feature Name. This is the only required field — you can save immediately and add more detail later.</li><li>Optionally add a Description. The more context you provide, the better any AI-generated documents will be.</li><li>Save the Feature. It now appears in your backlog.</li></ol><h3 id="option-b-from-a-roadmap" tabindex="-1">Option B: From a Roadmap <a class="header-anchor" href="#option-b-from-a-roadmap" aria-label="Permalink to &quot;Option B: From a Roadmap&quot;">​</a></h3><p>If you&#39;re building out a Roadmap and a new idea comes to mind, you can type it directly into the Roadmap entry field. When you do, Lodestone automatically adds it to the Backlog as well. No extra step required.</p><h3 id="option-c-from-an-extract" tabindex="-1">Option C: From an Extract <a class="header-anchor" href="#option-c-from-an-extract" aria-label="Permalink to &quot;Option C: From an Extract&quot;">​</a></h3><p>When you accept an Extract — an AI-identified idea surfaced from a meeting transcript — it automatically becomes a Feature. The Feature Name and Description are carried over from the Extract.</p><blockquote><p><strong>Tip:</strong> Don&#39;t wait until you have full context to create a Feature. Lodestone is designed for ideas to start lightweight and grow richer over time. A name is enough to preserve the signal.</p></blockquote><hr><h2 id="importing-features-from-csv" tabindex="-1">Importing Features from CSV <a class="header-anchor" href="#importing-features-from-csv" aria-label="Permalink to &quot;Importing Features from CSV&quot;">​</a></h2><p>If you have a list of Features in a spreadsheet, you can import them directly into the Backlog using a CSV file.</p><ol><li>Navigate to the Backlog from the left-hand navigation.</li><li>Select the import option from the Backlog toolbar.</li><li>Upload your CSV file.</li><li>In the field mapping step, match each column in your CSV to the corresponding Lodestone field — Name, Description, Status, or evaluation inputs.</li><li>Confirm the mapping. Features are added to your backlog immediately.</li></ol><blockquote><p><strong>Tip:</strong> The only required mapping is Feature Name. Description is optional but recommended — Features imported with a description are ready for AI document generation without additional editing.</p></blockquote><blockquote><p><strong>Note:</strong> CSV import creates new Features only — it does not update existing ones. Importing a file with a name that already exists in your backlog will create a duplicate.</p></blockquote><hr><h2 id="editing-and-enriching-a-feature" tabindex="-1">Editing and Enriching a Feature <a class="header-anchor" href="#editing-and-enriching-a-feature" aria-label="Permalink to &quot;Editing and Enriching a Feature&quot;">​</a></h2><p>To open a Feature&#39;s detail view, click its name anywhere it appears in the backlog.</p><p>From the Feature Detail page you can:</p><ul><li>Edit the Feature Name and Description</li><li>Update the Feature&#39;s Status</li><li>Enter evaluation scores (Value, Effort, or whichever framework your team uses)</li><li>Generate and manage Documents for this Feature (PRD, Opportunity Canvas, User Stories, and more)</li><li>Build a <strong>Financial Forecast</strong> for this Feature — modeling expected costs, revenue impact, and ROI</li><li>Link parent objects (including Goals) using the <strong>Parents</strong> field in the sidebar</li></ul><p>The Feature Detail page is organized into tabs. The first tab contains the core Feature information and Documents. The second tab, <strong>Financial Forecast</strong>, is where you create and manage financial models.</p><p>There&#39;s no required sequence — enrich a Feature however and whenever it makes sense.</p><hr><h2 id="linking-a-parent-object" tabindex="-1">Linking a Parent Object <a class="header-anchor" href="#linking-a-parent-object" aria-label="Permalink to &quot;Linking a Parent Object&quot;">​</a></h2><p>The <strong>Parents</strong> field in the Backlog item detail sidebar lets you connect any item to a parent in the object hierarchy — including a Goal.</p><p><strong>To add a parent:</strong></p><ol><li>Open the item detail page by clicking the item&#39;s name in the Backlog.</li><li>Find the <strong>Parents</strong> field in the sidebar.</li><li>Click the search field that appears and type to search for the parent object by name.</li><li>Select the parent from the results. It appears as a chip showing the typed ID and name.</li></ol><p>You can add multiple parents if the item contributes to more than one Goal or parent object.</p><p><strong>To remove a parent:</strong></p><p>Click the × on any parent chip. The connection is removed immediately.</p><blockquote><p><strong>Note:</strong> If your organization has configured parent/child type constraints in Settings &gt; Taxonomy, the search picker filters to only show objects of types that are allowed as parents for this item&#39;s type. If you see fewer results than expected, this is why.</p></blockquote><hr><h2 id="updating-feature-status" tabindex="-1">Updating Feature Status <a class="header-anchor" href="#updating-feature-status" aria-label="Permalink to &quot;Updating Feature Status&quot;">​</a></h2><p>Feature status can be updated in several places:</p><ul><li>From the Backlog — inline status change</li><li>From the Feature Detail page</li><li>From a Release board — drag the Feature card to a new column</li></ul><p>Regardless of where you update it, the change propagates everywhere. A status update in a Release is reflected in the backlog, and vice versa.</p><blockquote><p><strong>Important:</strong> Status stages are configured globally in Settings. If you need a stage that doesn&#39;t exist yet (e.g. &quot;In Review&quot; or &quot;Blocked&quot;), an admin can add it there.</p></blockquote><hr><h2 id="scoring-and-evaluating-features" tabindex="-1">Scoring and Evaluating Features <a class="header-anchor" href="#scoring-and-evaluating-features" aria-label="Permalink to &quot;Scoring and Evaluating Features&quot;">​</a></h2><p>Evaluation fields appear on the Feature Detail page. Which fields are shown depends on the evaluation framework configured in Settings.</p><h3 id="entering-scores" tabindex="-1">Entering scores <a class="header-anchor" href="#entering-scores" aria-label="Permalink to &quot;Entering scores&quot;">​</a></h3><ol><li>Open the Feature Detail page by clicking the Feature name.</li><li>Locate the evaluation section (typically on the right side or below the description).</li><li>Enter values for each scoring input (e.g. Reach, Impact, Confidence, Effort for RICE).</li><li>Lodestone calculates the composite score automatically.</li></ol><p>Scores appear in the Backlog, where you can sort and compare Features by their evaluation results.</p><h3 id="changing-your-evaluation-framework" tabindex="-1">Changing your evaluation framework <a class="header-anchor" href="#changing-your-evaluation-framework" aria-label="Permalink to &quot;Changing your evaluation framework&quot;">​</a></h3><p>You can switch evaluation frameworks at any time in Settings. This changes which fields are displayed — it doesn&#39;t delete previously entered scores or alter what the Feature represents.</p><hr><h2 id="adding-a-feature-to-a-roadmap" tabindex="-1">Adding a Feature to a Roadmap <a class="header-anchor" href="#adding-a-feature-to-a-roadmap" aria-label="Permalink to &quot;Adding a Feature to a Roadmap&quot;">​</a></h2><ol><li>Open the Roadmap you want to add the Feature to.</li><li>In the item entry field, start typing the Feature name.</li><li>Select it from the dropdown that appears — this links the existing Feature rather than creating a duplicate.</li><li>Position it in the hierarchy using drag-and-drop nesting.</li></ol><p>A Feature can be added to multiple Roadmaps. There is no limit.</p><hr><h2 id="adding-a-feature-to-a-release" tabindex="-1">Adding a Feature to a Release <a class="header-anchor" href="#adding-a-feature-to-a-release" aria-label="Permalink to &quot;Adding a Feature to a Release&quot;">​</a></h2><ol><li>Open the Release you want to populate.</li><li>Use the Feature dropdown to select Features from your backlog.</li><li>Selected Features appear as cards in the Kanban board under their current status column.</li></ol><p>Like Roadmaps, Features can belong to multiple Releases simultaneously.</p><hr><h2 id="generating-documents-for-a-feature" tabindex="-1">Generating Documents for a Feature <a class="header-anchor" href="#generating-documents-for-a-feature" aria-label="Permalink to &quot;Generating Documents for a Feature&quot;">​</a></h2><p>Lodestone can generate a range of written artifacts directly from a Feature. See the Documents module guide for full detail, but the quick workflow is:</p><ol><li>Open the Feature Detail page.</li><li>Scroll to or navigate to the Documents section.</li><li>Choose a document type (e.g. PRD, Opportunity Canvas, User Stories).</li><li>Click Generate. Lodestone uses the Feature Name, Description, and your Organization Description to produce a first draft.</li><li>Review and edit the output — all generated content is fully editable.</li></ol><blockquote><p><strong>Tip:</strong> The quality of AI-generated documents is directly tied to the richness of your Feature Description. A one-sentence description produces a thin document. A well-written paragraph produces a much more useful draft.</p></blockquote><hr><h2 id="viewing-and-managing-quotes-on-a-feature" tabindex="-1">Viewing and Managing Quotes on a Feature <a class="header-anchor" href="#viewing-and-managing-quotes-on-a-feature" aria-label="Permalink to &quot;Viewing and Managing Quotes on a Feature&quot;">​</a></h2><p>When a quote from an Extract or imported transcript is associated with a Feature, it appears in the <strong>Quotes</strong> section of the Feature Detail page. Quotes link product decisions back to real customer conversations.</p><p>Each quote displays:</p><ul><li>The quote text</li><li><strong>Company name</strong>, <strong>speaker name</strong>, and <strong>revenue</strong> (where available from the source)</li><li>A source badge indicating its origin (Gong, Fireflies, Manual, or Intel Report)</li></ul><h3 id="editing-a-quote" tabindex="-1">Editing a quote <a class="header-anchor" href="#editing-a-quote" aria-label="Permalink to &quot;Editing a quote&quot;">​</a></h3><p>Click directly on any quote field to edit the text, company name, or speaker in place.</p><h3 id="deleting-a-quote" tabindex="-1">Deleting a quote <a class="header-anchor" href="#deleting-a-quote" aria-label="Permalink to &quot;Deleting a quote&quot;">​</a></h3><p>Click the delete icon on a quote to remove it from the Feature. Deletion is permanent — the quote is removed from this Feature&#39;s quote library and cannot be recovered.</p><hr><h2 id="deleting-a-feature" tabindex="-1">Deleting a Feature <a class="header-anchor" href="#deleting-a-feature" aria-label="Permalink to &quot;Deleting a Feature&quot;">​</a></h2><p>Deleting a Feature is permanent. When a Feature is deleted, it is removed from any Roadmaps, Releases, or Strategies it belonged to. Associated Documents are deleted along with it.</p><blockquote><p><strong>Warning:</strong> There is no undo. If you delete a Feature by mistake, you will need to recreate it manually.</p></blockquote><hr><p><em>Next: Advanced &amp; Customization — object types, evaluation frameworks, and power-user options.</em></p>',76)])])}const g=a(r,[["render",n]]);export{p as __pageData,g as default};
